(()=>{const cfg=window.TIVIONE_CONFIG;const wa=(a,label)=>{a.href=cfg.urls.whatsapp+'?text='+encodeURIComponent('Hello '+cfg.brand+', I am interested in: '+label);a.target='_blank';a.rel='noopener'};document.querySelector('.breadcrumbs')?.remove();if(['/pricing/','/reseller/'].includes(location.pathname)){document.querySelectorAll('.button').forEach(a=>{const card=a.closest('.card'),name=card?.querySelector('h3')?.textContent||a.textContent.trim();wa(a,name)})}document.querySelectorAll('.footer').forEach(f=>{const box=document.createElement('div');box.className='wrap';box.style.cssText='font-size:.88rem;padding-top:18px;color:#aeb9df';box.innerHTML='Contact: WhatsApp +'+cfg.contact.whatsapp+' · Telegram @'+cfg.contact.telegram+' · '+cfg.contact.email;f.append(box)});})();
